import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// 冻结生成环境，避免维护者本机升级 Node 后悄悄改变可接受的键名。
if (process.versions.unicode !== '17.0') {
    throw new Error(`expected Unicode 17.0, got ${process.versions.unicode}`);
}

const start = /\p{ID_Start}/u;
const part = /\p{ID_Continue}/u;
const space = /\p{Zs}/u;
const ranges = [];
let begin = 0;
let previous = -1;

for (let codepoint = 0; codepoint <= 0x110000; codepoint++) {
    const ch = codepoint <= 0x10ffff ? String.fromCodePoint(codepoint) : '';
    const flags = codepoint <= 0x10ffff
        ? (start.test(ch) ? 1 : 0) | (part.test(ch) ? 2 : 0) | (space.test(ch) ? 4 : 0)
        : 0;
    if (flags === previous) continue;
    if (previous > 0) ranges.push([begin, codepoint - 1, previous]);
    begin = codepoint;
    previous = flags;
}

const lines = [
    '/* Generated by gen_unicode_table.mjs, Unicode 17.0. Do not edit manually. */',
    '/* Unicode data license: https://www.unicode.org/license.txt */',
    '/* Flags: ID_Start=1, ID_Continue=2, Space_Separator=4. */',
    'static const struct pdjson_unicode_range pdjson_unicode_ranges[] = {'
];
for (const [first, last, flags] of ranges) {
    lines.push(`  {0x${first.toString(16).toUpperCase()}, 0x${last.toString(16).toUpperCase()}, ${flags}},`);
}
lines.push('};', '');
const output = path.join(path.dirname(fileURLToPath(import.meta.url)), 'pdjson5_unicode.inc');
fs.writeFileSync(output, lines.join('\n'), 'utf8');
console.log(`wrote ${ranges.length} ranges to ${output}`);
